python - <<'PY'
import json,math
with open('benchmark/source_data.json') as f:
  d=json.load(f)
# build maps
sdr={r['country']:r['supply_demand_ratio'] for r in d['water_supply_demand']['data']}
stress={r['country']:r['stress_class'] for r in d['water_supply_demand']['data']}
pc={r['country']:r['per_capita_m3'] for r in d['per_capita_freshwater']['data']}
gw={r['country']:r['extraction_recharge_ratio'] for r in d['groundwater_extraction']['data']}
# precip trend slope from 1990s->2010s
from collections import defaultdict
p=defaultdict(dict)
for r in d['precipitation_trends']['data']:
  p[r['country']][r['decade']]=r['mean_precip_mm']
trend={c: p[c]['2010s']-p[c]['1990s'] for c in p}
# compute min/max for normalization (risk direction)
# supply/demand: lower is worse so use (max - x)/(max-min)
min_s=min(sdr.values()); max_s=max(sdr.values())
min_pc=min(pc.values()); max_pc=max(pc.values())
min_g=min(gw.values()); max_g=max(gw.values())
min_t=min(trend.values()); max_t=max(trend.values())

def norm_supply(x):
  return (max_s-x)/(max_s-min_s)

def norm_pcval(x):
  # lower per-capita worse
  return (max_pc-x)/(max_pc-min_pc)

def norm_gwval(x):
  return (x-min_g)/(max_g-min_g)

def norm_trend(x):
  # more negative worse
  return (max_t-x)/(max_t-min_t)

comp={}
for c in sdr:
  comp[c]=0.35*norm_supply(sdr[c])+0.25*norm_gwval(gw[c])+0.25*norm_pcval(pc[c])+0.15*norm_trend(trend[c])

rank=sorted(comp.items(), key=lambda kv: kv[1], reverse=True)
print('ranking')
for c,v in rank:
  print(c, round(v,3), 'SDR',sdr[c],'GW',gw[c],'pc',pc[c],'trend',trend[c])
PY

